import{_ as i,o as e,c as s,ae as a}from"./chunks/framework.DPZ3sAUK.js";const p=JSON.parse('{"title":"Scripts and Rules","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/scripts-and-rules.md","filePath":"concepts/scripts-and-rules.md"}'),o={name:"concepts/scripts-and-rules.md"};function n(l,t,r,c,d,h){return e(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="scripts-and-rules" tabindex="-1">Scripts and Rules <a class="header-anchor" href="#scripts-and-rules" aria-label="Permalink to &quot;Scripts and Rules&quot;">​</a></h1><p>Execution logic in <code>neuron-js</code> is defined via an <strong>ExecutionScript</strong>.</p><h2 id="executionscript-structure" tabindex="-1">ExecutionScript Structure <a class="header-anchor" href="#executionscript-structure" aria-label="Permalink to &quot;ExecutionScript Structure&quot;">​</a></h2><p>A script is essentially a collection of <strong>Rules</strong>. When a script is executed, the engine iterates through these rules in the order they are defined.</p><h2 id="the-anatomy-of-a-rule" tabindex="-1">The Anatomy of a Rule <a class="header-anchor" href="#the-anatomy-of-a-rule" aria-label="Permalink to &quot;The Anatomy of a Rule&quot;">​</a></h2><p>A <code>Rule</code> is a self-contained logical unit. It consists of two main parts:</p><ol><li><strong>Conditions</strong>: A list of checks that must pass for the rule to fire. If this list is empty, the rule is considered an <strong>&quot;Always&quot;</strong> rule and will always execute its actions.</li><li><strong>Actions</strong>: A list of operations to perform if the conditions pass. If this list is empty, the rule will <strong>&quot;Do Nothing&quot;</strong>—it will evaluate conditions but trigger no side effects.</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HighValueCustomerRule&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;conditions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;actions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="condition-logic" tabindex="-1">Condition Logic <a class="header-anchor" href="#condition-logic" aria-label="Permalink to &quot;Condition Logic&quot;">​</a></h2><p>Conditions are evaluated sequentially and follow a <strong>Sum of Products</strong> logic (ANDs grouped by ORs).</p><h3 id="and-logic" tabindex="-1">AND Logic <a class="header-anchor" href="#and-logic" aria-label="Permalink to &quot;AND Logic&quot;">​</a></h3><p>By default, all conditions in the list are joined by <strong>AND</strong>. Every condition must evaluate to <code>true</code> for the actions to trigger.</p><h3 id="or-grouping" tabindex="-1">OR Grouping <a class="header-anchor" href="#or-grouping" aria-label="Permalink to &quot;OR Grouping&quot;">​</a></h3><p>You can create an <strong>OR</strong> relationship by setting <code>orCondition: true</code> in a condition&#39;s options. This starts a <strong>new block</strong> of conditions.</p><ul><li>Each block is evaluated as an <strong>AND</strong> group.</li><li>All blocks are joined by <strong>OR</strong>.</li><li>If <strong>any</strong> block evaluates to <code>true</code>, the rule fires.</li></ul><p><strong>Example result</strong>: <code>(Block 1 AND Block 1) OR (Block 2 AND Block 2)</code></p><h3 id="advanced-features" tabindex="-1">Advanced Features: <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features:&quot;">​</a></h3><ul><li><strong>Inversion</strong>: Set <code>inverted: true</code> to negate a condition (NOT logic).</li><li><strong>Disabling</strong>: Rules or individual conditions can be disabled via options without removing them from the script.</li></ul><h2 id="sequential-execution" tabindex="-1">Sequential Execution <a class="header-anchor" href="#sequential-execution" aria-label="Permalink to &quot;Sequential Execution&quot;">​</a></h2><p>If a rule&#39;s conditions are met:</p><ol><li>The actions within that rule are executed one by one.</li><li>Each action can modify the <code>ExecutionContext</code>.</li><li>The modified context is passed to the next action, and eventually to the next rule in the script.</li></ol><p>This sequential nature allows for &quot;pipelining&quot; logic, where earlier rules prepare data or set flags for later rules to consume.</p>`,22)])])}const g=i(o,[["render",n]]);export{p as __pageData,g as default};
